(7181704, 1103927, 124190, '<td valign="top">This image made me stop to find out what you might be conveying.   Very imaginative use of the light bokeh which looks like time passage to me before I even found out that I must see this movie. I sure hope you just rolled in some dirt.  High mark.</td>', 'This image made me stop to find out what you might be conveying.   Very imaginative use of the light bokeh which looks like time passage to me before I even found out that I must see this movie. I sure hope you just rolled in some dirt.  High mark.', '2014-02-26 08:53:09.000000', NULL, 1),
(7181705, 1103675, 124190, '<td valign="top">Inviting colors, shapes, lighting.....depth of field.  Even though he is not.</td>', 'Inviting colors, shapes, lighting.....depth of field.  Even though he is not.', '2014-02-26 08:54:25.000000', NULL, 1),
(7181710, 1103360, 124190, '<td valign="top">Love the concept, poses, composition and models.   How DID you achieve what looks like motion blur in minimal editing!??</td>', 'Love the concept, poses, composition and models.   How DID you achieve what looks like motion blur in minimal editing!??', '2014-02-26 09:07:19.000000', NULL, 1),
(7181715, 1103381, 124190, '<td valign="top">He definitely looks removed.   I see some foreground blur creating the depth of field. His clenched hand, is it in a glove?   The subject is more interesting than the bokeh.</td>', 'He definitely looks removed.   I see some foreground blur creating the depth of field. His clenched hand, is it in a glove?   The subject is more interesting than the bokeh.', '2014-02-26 09:15:40.000000', NULL, 1),
