(7181835, 1103864, 12611, '<td valign="top">A dizzying reminder of eyelids.</td>', 'A dizzying reminder of eyelids.', '2014-02-26 16:20:35.000000', NULL, 1),
(7181860, 1103707, 163430, '<td valign="top">Too much bokeh in the foreground, if you ask me.</td>', 'Too much bokeh in the foreground, if you ask me.', '2014-02-26 17:52:16.000000', NULL, 1),
(7181873, 1103803, 163430, '<td valign="top">I don''t get it :-(</td>', 'I don''t get it :-(', '2014-02-26 18:08:24.000000', NULL, 1),
(7181875, 1103283, 163430, '<td valign="top">WOW!<br/>I have no idea where to horizon is... and i love it! The blurry sand (or whatever it is) simply guides you towards the boats.<br/>I wonder how it would look like in B/W and with some more contrast. Or with more saturated colors. I have a feeling that there is even more potential in this photo if only the rules were not Minimal Editing.</td>', 'WOW!I have no idea where to horizon is... and i love it! The blurry sand (or whatever it is) simply guides you towards the boats.I wonder how it would look like in B/W and with some more contrast. Or with more saturated colors. I have a feeling that there is even more potential in this photo if only the rules were not Minimal Editing.', '2014-02-26 18:15:07.000000', NULL, 1),
(7181885, 1103904, 163430, '<td valign="top">Y u no B/W? :-)</td>', 'Y u no B/W? :-)', '2014-02-26 18:27:23.000000', NULL, 1),
(7181887, 1103893, 163430, '<td valign="top">WOW!<br/>Love it.<br/>I would have gone with more contrast. Whiter whites and darker blacks.<br/>The tilt to the right is also effective.</td>', 'WOW!Love it.I would have gone with more contrast. Whiter whites and darker blacks.The tilt to the right is also effective.', '2014-02-26 18:30:28.000000', NULL, 1),
(7181891, 1103633, 163430, '<td valign="top">I both love it and hate it.<br/>I would have rotated the subject ~120 degrees to the left and focused on the part with the hands (1,2). Or set the watch/clock to 09:45, or maybe 11:40 :-)</td>', 'I both love it and hate it.I would have rotated the subject ~120 degrees to the left and focused on the part with the hands (1,2). Or set the watch/clock to 09:45, or maybe 11:40 :-)', '2014-02-26 18:39:34.000000', NULL, 1),
(7181894, 1103577, 163430, '<td valign="top">The bokeh in the foreground dosen''t look much effective to me.<br/>That aside, it would have been a pretty good landscape photo (the colors especially on the layers of mountains in the background) if only that darn horizon wasn''t dead center.</td>', 'The bokeh in the foreground dosen''t look much effective to me.That aside, it would have been a pretty good landscape photo (the colors especially on the layers of mountains in the background) if only that darn horizon wasn''t dead center.', '2014-02-26 18:42:39.000000', NULL, 1),
(7181895, 1103208, 163430, '<td valign="top">Interesting idea.<br/>Did you try B/W with extra contrast and sharpness?</td>', 'Interesting idea.Did you try B/W with extra contrast and sharpness?', '2014-02-26 18:46:17.000000', NULL, 1),
(7181900, 1103828, 12076, '<td valign="top">This works.  I tried a similar shot with a trumpet for this challenge but didn''t like it.</td>', 'This works.  I tried a similar shot with a trumpet for this challenge but didn''t like it.', '2014-02-26 18:52:31.000000', NULL, 1),
